package vn.svframe.lively.integration;
import vn.svframe.lively.api.HologramBridge;import java.lang.reflect.Method;import java.util.List;import java.util.function.Consumer;
/** Optional packet-hologram bridge verified against HoloDisplays 0.4.8 public API. */
final class HoloDisplaysBridge implements HologramBridge{private final Object api;private HoloDisplaysBridge(Object a){api=a;}static HologramBridge create(){try{Class<?>c=Class.forName("dev.furq.holodisplays.api.HoloDisplaysAPI");return new HoloDisplaysBridge(c.getMethod("get",String.class).invoke(null,"livelynpcs"));}catch(ReflectiveOperationException e){return HologramBridge.unavailable();}}@Override public boolean available(){return api!=null;}@Override public boolean remove(String id){try{return Boolean.TRUE.equals(api.getClass().getMethod("unregisterHologram",String.class).invoke(api,id));}catch(ReflectiveOperationException e){return false;}}@Override public boolean upsertText(String id,String world,double x,double y,double z,List<String> lines){try{String displayId=id+"_text";Method createText=api.getClass().getMethod("createTextDisplay",String.class,Consumer.class);Consumer<Object> configure=builder->{try{builder.getClass().getMethod("text",String[].class).invoke(builder,(Object)lines.toArray(String[]::new));builder.getClass().getMethod("billboardMode",String.class).invoke(builder,"CENTER");}catch(ReflectiveOperationException error){throw new IllegalStateException(error);}};createText.invoke(api,displayId,configure);Object hb=api.getClass().getMethod("createHologramBuilder").invoke(api);hb=call(hb,"position",new Class[]{float.class,float.class,float.class},(float)x,(float)y,(float)z);hb=call(hb,"world",new Class[]{String.class},world);hb=call(hb,"billboardMode",new Class[]{String.class},"CENTER");hb=call(hb,"addDisplay",new Class[]{String.class},displayId);Object data=hb.getClass().getMethod("build").invoke(hb);boolean exists=Boolean.TRUE.equals(api.getClass().getMethod("isHologramRegistered",String.class).invoke(api,id));Class<?>type=Class.forName("dev.furq.holodisplays.data.HologramData");Method operation=api.getClass().getMethod(exists?"updateHologram":"registerHologram",String.class,type);return Boolean.TRUE.equals(operation.invoke(api,id,data));}catch(ReflectiveOperationException|RuntimeException e){return false;}}private static Object call(Object target,String method,Class<?>[]types,Object...args)throws ReflectiveOperationException{return target.getClass().getMethod(method,types).invoke(target,args);}}
